# Instructions ----
#' This file follows the format generated by FIMS:::use_testthat_template().
#' Necessary tests include input and output (IO) correctness [IO
#' correctness], edge-case handling [Edge handling], and built-in errors and
#' warnings [Error handling]. See `?FIMS:::use_testthat_template` for more
#' information. Every test should have a @description tag, which can only span
#' one lines, that will be used in the bookdown report of the results from
#' {testthat}. This line can be more than 80 characters.

# normal_lpdf ----
## Setup ----
# 3 observations, each with its own expected value and sd.
observed <- c(1.2, 0.3, -0.5)
expected <- c(1, 0, 0)
standard_deviation <- c(0.5, 1, 2)

## IO correctness ----
test_that("`normal_lpdf()` works with correct inputs", {
  #' @description Test that `normal_lpdf()` returns the normal log density of each observation, as `stats::dnorm()` does.
  expect_equal(
    object = FIMS:::normal_lpdf(observed, expected, log(standard_deviation)),
    expected = stats::dnorm(observed, expected, standard_deviation, log = TRUE)
  )
  #' @description Test that `normal_lpdf()` returns -log(2 pi) / 2 for an observation equal to its expected value with an sd of 1.
  expect_equal(
    object = FIMS:::normal_lpdf(3, 3, log(1)),
    expected = -log(2 * pi) / 2
  )
})

## Edge handling ----
test_that("`normal_lpdf()` returns correct outputs for edge cases", {
  #' @description Test that `normal_lpdf()` returns 0 for a missing observation, so it adds nothing to the likelihood.
  expect_equal(
    object = FIMS:::normal_lpdf(c(1.2, NA), 1, log(0.5)),
    expected = c(stats::dnorm(1.2, 1, 0.5, log = TRUE), 0)
  )
})

## Error handling ----
test_that("`normal_lpdf()` returns correct error messages", {
  #' @description Test that `normal_lpdf()` errors when there are 2 expected values for 3 observations, rather than recycling them.
  expect_error(
    object = FIMS:::normal_lpdf(c(1, 2, 3), c(0, 1), log(1)),
    regexp = "1 value, or 1 per observation"
  )
})

# lognormal_lpdf ----
## Setup ----
# 3 positive observations, with expected values on the log scale.
observed_positive <- c(2, 10, 0.5)
log_expected <- c(log(2.5), log(8), 0)

## IO correctness ----
test_that("`lognormal_lpdf()` works with correct inputs", {
  #' @description Test that `lognormal_lpdf()` returns the lognormal log density of each observation, as `stats::dlnorm()` does.
  expect_equal(
    object = FIMS:::lognormal_lpdf(
      observed_positive, log_expected, log(standard_deviation)
    ),
    expected = stats::dlnorm(
      observed_positive, log_expected, standard_deviation,
      log = TRUE
    )
  )
  # The density of the observation itself includes the Jacobian -log(x): at
  # x = e, with log(x) equal to its expected value and an sd of 1, the log
  # density is -log(2 pi) / 2 - 1.
  #' @description Test that `lognormal_lpdf()` includes the -log(x) term, so x = e at its expected value with an sd of 1 returns -log(2 pi) / 2 - 1.
  expect_equal(
    object = FIMS:::lognormal_lpdf(exp(1), 1, log(1)),
    expected = -log(2 * pi) / 2 - 1
  )
})

## Edge handling ----
test_that("`lognormal_lpdf()` returns correct outputs for edge cases", {
  #' @description Test that `lognormal_lpdf()` returns 0 for a missing observation, so it adds nothing to the likelihood.
  expect_equal(
    object = FIMS:::lognormal_lpdf(c(2, NA), log(2.5), log(0.5)),
    expected = c(stats::dlnorm(2, log(2.5), 0.5, log = TRUE), 0)
  )
  #' @description Test that `lognormal_lpdf()` returns -Inf for an observation of 0, which has no density on the log scale.
  expect_equal(
    object = FIMS:::lognormal_lpdf(0, 0, log(1)),
    expected = -Inf
  )
})

## Error handling ----
test_that("`lognormal_lpdf()` returns correct error messages", {
  #' @description Test that `lognormal_lpdf()` errors when there are 2 log expected values for 3 observations, rather than recycling them.
  expect_error(
    object = FIMS:::lognormal_lpdf(c(1, 2, 3), c(0, 1), log(1)),
    regexp = "1 value, or 1 per observation"
  )
})
